<script module lang="ts">
/**
 * The create/edit screen (`design/archetypes/form-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/form-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/form-page.module.css'
import Inline from '../layout/Inline.svelte'
import PageHeader from '../structure/PageHeader.svelte'

export interface FormPageProps {
  /**
   * The submit row, with exactly one `solid` Button and quieter variants for the rest.
   */
  actions: Snippet
  /**
   * Cards of FormFields.
   */
  children: Snippet
  description?: string
  onSubmit?: () => void
  title: string
}
</script>

<script lang="ts">
let { actions, children, description, onSubmit, title }: FormPageProps = $props()
const joined = joinSlot(undefined, () => ({}))
const listening = {
  get submit() {
    return onSubmit !== undefined
  },
}
let form = $state<HTMLElement | null>(null)
const submit = $derived((event: Event) => {
  event.preventDefault()
  const invalid = form?.querySelector<HTMLElement>('[aria-invalid="true"]')
  if (invalid) {
    invalid.focus()
    return
  }
  onSubmit?.()
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.page} data-member="form-page"
    ><PageHeader {title} {description}
    />{#if listening.submit
      }<form
        bind:this={form}
        class={styles.form}
        novalidate={true}
        onsubmit={(event) => { submit(event) }}
        >{@render children?.()
        }<div class={styles.actions}
          ><Inline gap={3} justify="end" wrap={true}>{@render actions?.()}</Inline
        ></div
      ></form
    >{:else
      }{@render children?.()
      }<div class={styles.actions}
        ><Inline gap={3} justify="end" wrap={true}>{@render actions?.()}</Inline
      ></div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
